using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Define tools available to the agent
var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information on a given query and returns relevant results."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note with key findings")] string content) =>
        noteService.SaveNote(title, content),
        "save_note",
        "Saves a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        () => noteService.GetAllNotes(),
        "get_notes",
        "Retrieves all saved research notes."),
};

// Create the agent using Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the web_search tool
        2. Saving key findings as notes using the save_note tool
        3. After gathering enough information (at least 2-3 searches), retrieve your notes
           and provide a comprehensive summary of your findings.

        Be thorough but concise. Focus on factual information from reliable sources.
        """,
};

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 50));

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine($"\n{new string('-', 50)}");
Console.WriteLine("\nSaved Notes:");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"  • {note}");
}

// --- Tool Implementations ---

/// <summary>
/// Simulated web search tool that uses a public search API.
/// Replace with a real search API (Bing, Google, Brave) for production use.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  [🔍 Searching: \"{query}\"]");
        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1";
            var response = await Http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            if (response.TryGetProperty("AbstractText", out var abs) &&
                abs.GetString() is { Length: > 0 } abstractText)
            {
                results.Add($"Summary: {abstractText}");
            }

            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(3))
                {
                    if (item.TryGetProperty("Text", out var text) &&
                        text.GetString() is { Length: > 0 } t)
                    {
                        results.Add(t);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
sealed class NoteService
{
    private readonly List<(string Title, string Content)> _notes = [];

    public string SaveNote(string title, string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  [📝 Note saved: \"{title}\"]");
        return $"Note '{title}' saved successfully.";
    }

    public List<string> GetAllNotes() =>
        _notes.Select(n => $"[{n.Title}]: {n.Content}").ToList();
}

